      ('Pre-facelift'::text, 'Sedan 4-door'::text, 'CUNA'::text, 135::integer, 'MQ350'::text, null::text),
      ('Pre-facelift'::text, 'Hatchback 3-door'::text, 'CUNA'::text, 135::integer, 'DQ250'::text, null::text),
      ('Pre-facelift'::text, 'Hatchback 5-door'::text, 'CUNA'::text, 135::integer, 'DQ250'::text, null::text),
      ('Pre-facelift'::text, 'Sedan 4-door'::text, 'CUNA'::text, 135::integer, 'DQ250'::text, null::text),
      ('Pre-facelift'::text, 'Hatchback 3-door'::text, 'CUNA'::text, 135::integer, 'DQ250'::text, 'haldex_gen5'::text),
      ('Pre-facelift'::text, 'Hatchback 5-door'::text, 'CUNA'::text, 135::integer, 'DQ250'::text, 'haldex_gen5'::text),
      ('Pre-facelift'::text, 'Sedan 4-door'::text, 'CUNA'::text, 135::integer, 'DQ250'::text, 'haldex_gen5'::text)
  )
insert into catalog_vehicle_configurations (phase_id, body_type_id, engine_id, unit_id, drivetrain_id)
select p.id, b.id, e.id, u.id, d.id
from configs c
join phase_lookup p on p.phase_label = c.phase_label
join body_lookup b on b.name = c.body_name
join engine_lookup e on e.code = c.engine_code and e.power_kw = c.engine_power_kw
join unit_lookup u on u.code = c.unit_code or c.unit_code = any(u.alt_codes)
left join dt_lookup d on d.code = c.dt_code
on conflict (
  phase_id, body_type_id, engine_id, unit_id,
  coalesce(drivetrain_id, '00000000-0000-0000-0000-000000000000'::uuid)
) do nothing;

