insert into catalog_trims (phase_id, name, tier)
select p.id, v.name, v.tier
from (
  values
    ('Pre-facelift'::text, 'Attraction / Basis'::text, 1::integer),
    ('Facelift'::text, 'Attraction / Basis'::text, 1::integer),
    ('Pre-facelift'::text, 'Ambition / Sport'::text, 2::integer),
    ('Facelift'::text, 'Ambition / Sport'::text, 2::integer),
    ('Pre-facelift'::text, 'Ambiente / Design'::text, 2::integer),
    ('Facelift'::text, 'Ambiente / Design'::text, 2::integer),
    ('Pre-facelift'::text, 'S line'::text, 3::integer),
    ('Facelift'::text, 'S line'::text, 3::integer)
) as v(phase_label, name, tier)
join (
  select cp.id, cp.phase_label
  from catalog_phases cp
  join catalog_models cm on cm.id = cp.model_id
  join catalog_brands cb on cb.id = cm.brand_id
  where cb.name = 'Audi' and cm.name = 'A3' and cp.generation_code = '8V'
) as p on p.phase_label = v.phase_label
where not exists (
  select 1 from catalog_trims ct where ct.phase_id = p.id and ct.name = v.name
);

